import type { Request, Response } from "express";
import { buildGreeting, HttpError } from "../domain/greeting";

export function postGreeting(req: Request, res: Response) {
  try {
    res.json({ greeting: buildGreeting(req.body?.name) });
  } catch (error) {
    if (error instanceof HttpError) {
      res.status(error.status).json({ message: error.message });
      return;
    }

    throw error;
  }
}

